export type VideoResearchCapability =
  | "TRANSCRIPT"
  | "VIDEO_SEARCH"
  | "VIDEO_METADATA";

export type TranscriptSourceKind =
  | "CREATOR_CAPTIONS"
  | "AUTO_CAPTIONS"
  | "SPEECH_TO_TEXT"
  | "UNKNOWN";

export interface VideoTranscriptSegment {
  readonly startSeconds: number;
  readonly durationSeconds: number;
  readonly text: string;
}

export interface VideoTranscript {
  readonly providerId: string;
  readonly providerRequestId?: string;
  readonly videoId: string;
  readonly sourceUrl: string;
  readonly title?: string;
  readonly channel?: string;
  readonly channelId?: string;
  readonly language?: string;
  readonly translated?: boolean;
  readonly autoGenerated?: boolean;
  readonly sourceKind: TranscriptSourceKind;
  readonly durationSeconds?: number;
  readonly segments: readonly VideoTranscriptSegment[];
  readonly text: string;
  readonly retrievedAt: string;
}

export interface VideoSearchResult {
  readonly providerId: string;
  readonly providerRequestId?: string;
  readonly videoId: string;
  readonly sourceUrl: string;
  readonly title: string;
  readonly channel?: string;
  readonly channelId?: string;
  readonly description?: string;
  readonly publishedAt?: string;
  readonly thumbnailUrl?: string;
}

export interface VideoTranscriptOptions {
  readonly language?: string;
  readonly translateTo?: string;
  readonly timestamps?: boolean;
}

export interface VideoResearchProvider {
  readonly id: string;
  readonly capabilities: readonly VideoResearchCapability[];
  search(
    query: string,
    count: number,
  ): Promise<readonly VideoSearchResult[]>;
  transcript?(
    videoRef: string,
    options?: VideoTranscriptOptions,
  ): Promise<VideoTranscript>;
  health(): Promise<boolean>;
}

export class VideoResearchError extends Error {
  readonly providerId: string;
  readonly status?: number;
  readonly retryable: boolean;

  constructor(
    providerId: string,
    message: string,
    options: { status?: number; retryable?: boolean } = {},
  ) {
    super(message);
    this.name = "VideoResearchError";
    this.providerId = providerId;
    this.status = options.status;
    this.retryable = options.retryable ?? false;
  }
}

export function normalizeYouTubeVideoId(videoRef: string): string {
  const value = videoRef.trim();
  if (/^[A-Za-z0-9_-]{11}$/.test(value)) return value;

  try {
    const url = new URL(value);
    if (
      url.hostname === "youtu.be" ||
      url.hostname.endsWith(".youtu.be")
    ) {
      const id = url.pathname.split("/").filter(Boolean)[0];
      if (id && /^[A-Za-z0-9_-]{11}$/.test(id)) return id;
    }

    const queryId = url.searchParams.get("v");
    if (queryId && /^[A-Za-z0-9_-]{11}$/.test(queryId)) return queryId;

    const parts = url.pathname.split("/").filter(Boolean);
    const markerIndex = parts.findIndex((part) =>
      ["shorts", "embed", "live"].includes(part),
    );
    const markerId =
      markerIndex >= 0 ? parts[markerIndex + 1] : undefined;
    if (markerId && /^[A-Za-z0-9_-]{11}$/.test(markerId)) return markerId;
  } catch {
    // Fall through to the explicit validation error below.
  }

  throw new VideoResearchError(
    "video-research",
    "Unable to extract an 11-character YouTube video ID from the supplied reference.",
  );
}
